import sys
from functools import lru_cache

def get_max_sum(n):
    sys.setrecursionlimit(10000)

    @lru_cache(maxsize=None)
    def f(n):
        if n < 2:
            return n
        return max(f(n // 2) + f(n // 3) + f(n // 4) + f(n // 5), n)

    return f(n)

